for close,name,sc in re.findall(r'<(/?)([a-zA-Z][a-zA-Z0-9]*)\b[^>]*?(/?)>', s):
    n=name.lower()
    if n in VOID or sc: continue
    if close:
        if not stack or stack[-1]!=n: errs.append(f"</{n}>")
        else: stack.pop()
    else: stack.append(n)
print("unclosed:", stack or "none", "| errors:", errs[:3] or "none")
print("eyebrows:", re.findall(r'>(\d\d) &middot;', s))
stripped = re.sub(r':root[^{]*\{[^}]*\}', '', s)
stripped = re.sub(r'@media[^{]*\{\s*:root[^{]*\{[^}]*\}\s*\}', '', stripped)
bad=[(p,v) for p,v in re.findall(r'(?:^|\s)(color|background|border[a-z-]*|fill|stroke)\s*:\s*([^;{}]+)', stripped) if '#' in v]
print("non-token colours:", bad or "none")
